import{z as A,x as M,o as r,c as d,q as l,j as n,D as E,d as i,s,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Rice 定理","description":"","frontmatter":{"title":"Rice 定理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rice-theorem.md","filePath":"cs/rice-theorem.md","lastUpdated":1791413859000}'),p={name:"cs/rice-theorem.md"};function c(B,e,m,D,_,h){const t=M("Mermaid");return r(),d("div",null,[e[2]||(e[2]=l('<h1 id="rice-定理" tabindex="-1">Rice 定理 <a class="header-anchor" href="#rice-定理" aria-label="Permalink to &quot;Rice 定理&quot;">​</a></h1><div class="epigraph"><p>任何关于 $L(M)$ 的非平凡语义性质，作为机器编码的集合，都不可判定。</p><footer>—— 据 Rice, Classes of Recursively Enumerable Sets and Their Decision Problems, 1953 整理</footer></div><p>上一课<a href="/cs/mapping-reduction-undecidable">映射归约</a>会逐个构造 \\(M&#39;\\)。缺口是批量：只要性质谈的是<strong>语言</strong>而不是代码文本，并且不是「所有 RE 都是 / 都不是」，就不可判定。Rice 定理收掉「是否空、是否有限、是否等于 \\(\\Sigma^*\\)、是否正则」这一类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>性质 \\(P\\) 是一组 RE 语言。对应的指标集 \\(I_P=\\{\\langle M\\rangle\\mid L(M)\\in P\\}\\)。<span class="marginnote">「指标集」翻译成大白话：把所有语言满足性质 \\(P\\) 的机器编码打包成一个集合。要判定的问题只有一个——这台机器的编码在不在集合里。Rice 定理说：只要 \\(P\\) 非平凡，这个「在不在」就没算法可判。</span>非平凡：存在 \\(M_1,M_2\\)，\\(L(M_1)\\in P\\)、\\(L(M_2)\\notin P\\)。Rice：每个这样的 \\(I_P\\) 不可判定。证明骨架：把 \\(A_{\\mathrm{TM}}\\) 化到 \\(I_P\\)。不妨设 \\(\\emptyset\\notin P\\)（否则做补）。取固定的 \\(M_+\\) 使 \\(L(M_+)\\in P\\)。给定 \\(\\langle M,w\\rangle\\)，造 \\(M&#39;\\)：先模拟 \\(M(w)\\)，若接受再模拟 \\(M_+\\)。则 \\(L(M&#39;)=L(M_+)\\) 或 \\(\\emptyset\\)，于是 \\(\\langle M&#39;\\rangle\\in I_P\\iff M\\) 接受 \\(w\\)。</p><p>句法性质不在范围内：「\\(M\\) 是否恰有 5 个状态」可判定。语义是外延 \\(L(M)\\)。</p><h3 id="非平凡不能省" tabindex="-1">非平凡不能省 <a class="header-anchor" href="#非平凡不能省" aria-label="Permalink to &quot;非平凡不能省&quot;">​</a></h3><p>「\\(L(M)\\) 是 RE」是平凡的：所有 \\(M\\) 都是。平凡性质可判定（恒真或恒假）。Rice 不管复杂度，也不给出是否 RE。</p><p><span class="marginnote">Rice 1953。课堂常证「不可判定」这一半；Rice–Shapiro 等加强到 RE 指标集的形状，本课不进。与停机的差别：停机不是纯语言性质（依赖具体 \\(w\\) 上的运行）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>核对：问的是不是 \\(L(M)\\)？有没有正反例？有则直接引 Rice，不必新造对角化。若问的是「在输入 \\(0\\) 上是否停」，不是纯语义，回到归约。</p>',11)),(r(),n(o,null,{default:E(()=>[s(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEM%5B%22%E9%9D%9E%E5%B9%B3%E5%87%A1%E8%AF%AD%E4%B9%89%20P%22%5D%20--%3E%20IND%5B%22%E6%8C%87%E6%A0%87%E9%9B%86%20I_P%22%5D%0A%20%20ATM%5B%22A_TM%22%5D%20--%3E%7C%22%E6%A0%87%E5%87%86%20M%E2%80%B2%22%7C%20IND%0A%20%20IND%20--%3E%20UNDEC%5B%22%E4%B8%8D%E5%8F%AF%E5%88%A4%E5%AE%9A%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[a("a",{href:"/cs/cfg-grammar"},"CFG 等价"),i(" 在主干不可判定，那是文法对象；本课对象是 TM 指标。不要用 Rice 去打 DFA 等价——DFA 的语言性质许多可判定，因为描述不是通用 TM。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[i("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"定理依赖通用模拟：才能让 \\(M'\\) 在「先做 \\(M(w)\\)」之后变成另一台已知机器。有限自动机没有这种通用性，Rice 不适用。这解释为何词法器可以判定等价，而任意程序不能判定「是否认同一语言」。",-1)),e[6]||(e[6]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：\\(M'\\) 的构造把「\\(M\\) 是否接受 \\(w\\)」藏进了一个启动开关——只有 \\(M\\) 接受，\\(M'\\) 才表现成那台已知的好机器 \\(M_+\\)；否则它永远空转成空语言。于是原问题被原封不动翻译成「\\(\\langle M'\\rangle\\) 在不在指标集里」。")],-1)),(r(),n(o,null,{default:E(()=>[s(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%20%E2%9F%A8M%2C%20w%E2%9F%A9%22%5D%20--%3E%20BUILD%5B%22%E6%9E%84%E9%80%A0%20M%E2%80%B2%EF%BC%9A%E5%85%88%E6%A8%A1%E6%8B%9F%20M(w)%22%5D%0A%20%20BUILD%20--%3E%7C%22M%20%E6%8E%A5%E5%8F%97%20w%22%7C%20RUNP%5B%22%E7%BB%A7%E7%BB%AD%E6%A8%A1%E6%8B%9F%E5%9B%BA%E5%AE%9A%E6%9C%BA%E5%99%A8%20M%E2%82%8A%22%5D%0A%20%20BUILD%20--%3E%7C%22M%20%E4%B8%8D%E6%8E%A5%E5%8F%97%E6%88%96%E4%B8%8D%E5%81%9C%22%7C%20LOOP%5B%22M%E2%80%B2%20%E5%8E%9F%E5%9C%B0%E4%B8%8D%E5%81%9C%E6%9C%BA%22%5D%0A%20%20RUNP%20--%3E%20L1%5B%22L(M%E2%80%B2)%20%3D%20L(M%E2%82%8A)%EF%BC%8C%E5%B1%9E%20P%22%5D%0A%20%20LOOP%20--%3E%20L2%5B%22L(M%E2%80%B2)%20%3D%20%E2%88%85%EF%BC%8C%E4%B8%8D%E5%B1%9E%20P%22%5D%0A%20%20L1%20--%3E%20DEC%5B%22%E5%88%A4%E5%AE%9A%20%E2%9F%A8M%E2%80%B2%E2%9F%A9%20%E6%98%AF%E5%90%A6%E5%9C%A8%E6%8C%87%E6%A0%87%E9%9B%86%E9%87%8C%EF%BC%8C%E7%AD%89%E4%BB%B7%E4%BA%8E%E5%88%A4%E5%AE%9A%20M%20%E6%98%AF%E5%90%A6%E6%8E%A5%E5%8F%97%20w%22%5D%0A%20%20L2%20--%3E%20DEC%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=l('<p>Rice 不阻止近似、静态分析、受限语言上的判定；它阻止的是全 TM 类上的精确语义问题。</p><p>「\\(M\\) 是否在输入 \\(\\varepsilon\\) 上三步内停」不是语义：\\(L(M)\\) 相同的机器可以在 \\(\\varepsilon\\) 上行为不同（若谈的是具体运行）。Rice 只管外延。<span class="marginnote">常见误区：把「这段程序会不会崩」交给 Rice。判据是——换一台认同一语言的机器，结论会不会变？会变（如「三步内停」）就不是语义性质，要回归约；不变（如「语言非空」）才轮到 Rice。</span>指标集可以不可判定却仍 RE（如 \\(A_{\\mathrm{TM}}\\) 投影），也可以两边都不是 RE。定理只给不可判定这一口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证指标集是否 RE（有的是，有的连补都不是）。不引入 Rice 的全部推广。后课默认：见「任意程序的语言是否满足……」先查 Rice。下一课自指：递归定理。</p><p>受限程序分析（有限展开、抽象解释）可以对子类给答案，并不违反 Rice：它们放弃了全 TM 类上的精确语义。本课只禁止「任意程序 + 非平凡外延性质」的判定器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>非平凡的 \\(L(M)\\) 性质不可判定。</li><li>句法、特定输入上的运行，不在定理范围内。</li><li>证明是从 \\(A_{\\mathrm{TM}}\\) 到指标集的一张模板归约。</li><li>出处：Rice, 1953。</li></ul>',7))])}const P=A(p,[["render",c]]);export{C as __pageData,P as default};
